			renvoAsmMarkLabel(a, positive)
			if destKind == renvoTypeFloat32 {
				renvoAsmEmitText(a, "\xf3\x48\x0f\x2a\xc0\x66\x0f\x7e\xc0")
			} else {
				renvoAsmEmitText(a, "\xf2\x48\x0f\x2a\xc0\x66\x48\x0f\x7e\xc0")
			}
			renvoAsmMarkLabel(a, done)
